  1	<!doctype html>
  2	<html lang="en">
  3	<head>
  4	<meta charset="utf-8">
  5	<meta name="viewport" content="width=device-width, initial-scale=1">
  6	<title>Calculator</title>
  7	<style>
  8	  :root {
  9	    --bg: #eef0f3;
 10	    --body: #1c1f24;
 11	    --screen: #0f1115;
 12	    --text: #f5f6f8;
 13	    --key: #2a2e35;
 14	    --key-hover: #353a42;
 15	    --op: #f59e0b;
 16	    --op-hover: #fbb13c;
 17	    --fn: #9aa1ab;
 18	    --fn-hover: #b1b7bf;
 19	  }
 20	  * { box-sizing: border-box; }
 21	  html, body { height: 100%; }
 22	  body {
 23	    margin: 0;
 24	    display: flex;
 25	    align-items: center;
 26	    justify-content: center;
 27	    padding: 16px;
 28	    background: var(--bg);
 29	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
 30	  }
 31	  .calc {
 32	    width: 100%;
 33	    max-width: 340px;
 34	    padding: 20px;
 35	    border-radius: 24px;
 36	    background: var(--body);
 37	    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.25);
 38	  }
 39	  .display {
 40	    height: 96px;
 41	    margin-bottom: 16px;
 42	    padding: 0 12px;
 43	    display: flex;
 44	    align-items: flex-end;
 45	    justify-content: flex-end;
 46	    overflow: hidden;
 47	    border-radius: 14px;
 48	    background: var(--screen);
 49	    color: var(--text);
 50	    font-size: 48px;
 51	    font-weight: 300;
 52	    line-height: 1.6;
 53	    white-space: nowrap;
 54	    font-variant-numeric: tabular-nums;
 55	  }
 56	  .keys {
 57	    display: grid;
 58	    grid-template-columns: repeat(4, 1fr);
 59	    gap: 10px;
 60	  }
 61	  button {
 62	    height: 64px;
 63	    border: 0;
 64	    border-radius: 14px;
 65	    background: var(--key);
 66	    color: var(--text);
 67	    font: inherit;
 68	    font-size: 24px;
 69	    cursor: pointer;
 70	    transition: background 0.1s, transform 0.05s;
 71	    -webkit-tap-highlight-color: transparent;
 72	  }
 73	  button:hover { background: var(--key-hover); }
 74	  button:active { transform: scale(0.96); }
 75	  button:focus-visible { outline: 2px solid var(--op); outline-offset: 2px; }
 76	  .op { background: var(--op); color: #1c1f24; }
 77	  .op:hover { background: var(--op-hover); }
 78	  .op.active { background: var(--text); color: var(--op); }
 79	  .fn { background: var(--fn); color: #1c1f24; }
 80	  .fn:hover { background: var(--fn-hover); }
 81	  .wide { grid-column: span 2; }
 82	</style>
 83	</head>
 84	<body>
 85	<main class="calc">
 86	  <div class="display" data-testid="calc-display" data-value="0" role="status" aria-live="polite">0</div>
 87	  <div class="keys">
 88	    <button type="button" class="fn wide" data-testid="key-clear">AC</button>
 89	    <button type="button" class="op" data-testid="key-div" data-op="/" aria-label="Divide">÷</button>
 90	    <button type="button" class="op" data-testid="key-mul" data-op="*" aria-label="Multiply">×</button>
 91	
 92	    <button type="button" data-testid="key-7" data-digit="7">7</button>
 93	    <button type="button" data-testid="key-8" data-digit="8">8</button>
 94	    <button type="button" data-testid="key-9" data-digit="9">9</button>
 95	    <button type="button" class="op" data-testid="key-sub" data-op="-" aria-label="Subtract">−</button>
 96	
 97	    <button type="button" data-testid="key-4" data-digit="4">4</button>
 98	    <button type="button" data-testid="key-5" data-digit="5">5</button>
 99	    <button type="button" data-testid="key-6" data-digit="6">6</button>
100	    <button type="button" class="op" data-testid="key-add" data-op="+" aria-label="Add">+</button>
101	
102	    <button type="button" data-testid="key-1" data-digit="1">1</button>
103	    <button type="button" data-testid="key-2" data-digit="2">2</button>
104	    <button type="button" data-testid="key-3" data-digit="3">3</button>
105	    <button type="button" class="op" data-testid="key-equals" aria-label="Equals">=</button>
106	
107	    <button type="button" class="wide" data-testid="key-0" data-digit="0">0</button>
108	    <button type="button" data-testid="key-dot" aria-label="Decimal point">.</button>
109	  </div>
110	</main>
111	<script>
112	(function () {
113	  var MAX_DIGITS = 16;
114	
115	  var display = document.querySelector('[data-testid="calc-display"]');
116	  var opKeys = document.querySelectorAll('[data-op]');
117	
118	  // value: the number currently shown when no entry is being typed.
119	  // entry: the string being typed, or null.
120	  // acc/op: the left operand and pending operator.
121	  var state;
122	
123	  function reset() {
124	    state = { value: 0, entry: null, acc: null, op: null };
125	  }
126	
127	  function compute(a, op, b) {
128	    switch (op) {
129	      case '+': return a + b;
130	      case '-': return a - b;
131	      case '*': return a * b;
132	      case '/': return b === 0 ? NaN : a / b;
133	    }
134	    return b;
135	  }
136	
137	  function currentValue() {
138	    return state.entry !== null ? Number(state.entry) : state.value;
139	  }
140	
141	  function format(n) {
142	    if (!isFinite(n)) return 'Error';
143	    var s = String(Number(n.toPrecision(12)));
144	    if (s.replace(/[-.]/g, '').length > MAX_DIGITS) s = n.toExponential(8);
145	    return s;
146	  }
147	
148	  function render() {
149	    var value = currentValue();
150	    var text = state.entry !== null ? state.entry : format(value);
151	    display.textContent = text;
152	    display.setAttribute('data-value', String(value));
153	    display.style.fontSize = text.length > 12 ? Math.max(20, Math.floor(48 * 12 / text.length)) + 'px' : '';
154	    for (var i = 0; i < opKeys.length; i++) {
155	      var k = opKeys[i];
156	      k.classList.toggle('active', state.entry === null && state.op === k.getAttribute('data-op'));
157	    }
158	  }
159	
160	  function inputDigit(d) {
161	    if (!isFinite(state.value)) reset();
162	    var e = state.entry;
163	    if (e === null || e === '0') {
164	      state.entry = d;
165	    } else if (e.replace('.', '').length < MAX_DIGITS) {
166	      state.entry = e + d;
167	    }
168	  }
169	
170	  function inputDot() {
171	    if (!isFinite(state.value)) reset();
172	    if (state.entry === null) {
173	      state.entry = '0.';
174	    } else if (state.entry.indexOf('.') === -1) {
175	      state.entry += '.';
176	    }
177	  }
178	
179	  // Immediate execution: an operator key first finishes the operation already
180	  // waiting, strictly left to right, with no precedence (2 + 3 × 4 = 20).
181	  // The display then always shows a real running result.
182	  function inputOperator(op) {
183	    if (!isFinite(state.value)) return;
184	    if (state.entry !== null) {
185	      var b = Number(state.entry);
186	      state.value = state.op !== null ? compute(state.acc, state.op, b) : b;
187	      state.entry = null;
188	    }
189	    if (!isFinite(state.value)) {
190	      state.acc = null;
191	      state.op = null;
192	      return;
193	    }
194	    state.acc = state.value;
195	    state.op = op;
196	  }
197	
198	  function equals() {
199	    if (state.op === null) {
200	      if (state.entry !== null) {
201	        state.value = Number(state.entry);
202	        state.entry = null;
203	      }
204	      return;
205	    }
206	    var b = currentValue();
207	    state.value = compute(state.acc, state.op, b);
208	    state.entry = null;
209	    state.acc = null;
210	    state.op = null;
211	  }
212	
213	  function press(action) {
214	    action();
215	    render();
216	  }
217	
218	  document.querySelector('.keys').addEventListener('click', function (ev) {
219	    var btn = ev.target.closest('button');
220	    if (!btn) return;
221	    var id = btn.getAttribute('data-testid');
222	    if (btn.hasAttribute('data-digit')) {
223	      press(function () { inputDigit(btn.getAttribute('data-digit')); });
224	    } else if (btn.hasAttribute('data-op')) {
225	      press(function () { inputOperator(btn.getAttribute('data-op')); });
226	    } else if (id === 'key-dot') {
227	      press(inputDot);
228	    } else if (id === 'key-equals') {
229	      press(equals);
230	    } else if (id === 'key-clear') {
231	      press(reset);
232	    }
233	  });
234	
235	  document.addEventListener('keydown', function (ev) {
236	    if (ev.ctrlKey || ev.metaKey || ev.altKey) return;
237	    var k = ev.key;
238	    if (/^[0-9]$/.test(k)) {
239	      press(function () { inputDigit(k); });
240	    } else if (k === '.' || k === ',') {
241	      press(inputDot);
242	    } else if (k === '+' || k === '-' || k === '*' || k === '/') {
243	      press(function () { inputOperator(k); });
244	    } else if (k === 'Enter' || k === '=') {
245	      press(equals);
246	    } else if (k === 'Escape' || k === 'Delete') {
247	      press(reset);
248	    } else {
249	      return;
250	    }
251	    ev.preventDefault();
252	  });
253	
254	  reset();
255	  render();
256	})();
257	</script>
258	</body>
259	</html>

